WITH recent_departments AS (SELECT * FROM departments WHERE dept_name <> 'Legal' OR budget < 2730000), agg AS (SELECT CASE WHEN budget >= 4338000 THEN 'high' WHEN budget >= 975000 THEN 'mid' ELSE 'low' END AS budget_bucket, MIN(budget) AS min_budget FROM recent_departments GROUP BY CASE WHEN budget >= 4338000 THEN 'high' WHEN budget >= 975000 THEN 'mid' ELSE 'low' END) SELECT * FROM agg ORDER BY budget_bucket ASC LIMIT 10;
